cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

// Note: every quote carries the 10 % first-insurance surcharge and the 5 G fee.
// A newcomer (0 years) quoting a single item therefore pays ceil(base * 1.1 + 5).

describe("MHPCO Claim Office — quote", () => {
  describe("base premiums", () => {
    it.todo("should charge only the processing fee for an empty item list — 5 G");
    it.todo("should quote a sword (base 100 G) — 115 G");
    it.todo("should quote an amulet (base 60 G) — 71 G");
    it.todo("should quote a staff (base 80 G) — 93 G");
    it.todo("should quote a potion (base 40 G) — 49 G");
    it.todo("should quote a single rune component (base 25 G) — 33 G (32.5 rounded up)");
  });

  describe("building block of 3 alike components", () => {
    it.todo("should quote 2 runes without block (base 50 G) — 60 G");
    it.todo("should quote 3 runes as a block (base 60 G) — 71 G");
    it.todo("should quote 4 runes without block, block requires exactly 3 (base 100 G) — 115 G");
    it.todo("should quote 7 runes without block (base 175 G) — 198 G (197.5 rounded up in MHPCO's favor)");
    it.todo("should not form a block from 2 runes + 1 moonstone, different types (base 75 G) — 88 G");
    it.todo("should form two separate blocks from 3 runes + 3 moonstones (base 120 G) — 137 G");
  });

  describe("item-specific modifiers", () => {
    it.todo("should add 50 % curse surcharge to a cursed sword for a newcomer — 165 G");
    it.todo("should add 30 % high-enchantment surcharge to a sword with exactly enchantment 5 — 148 G");
    it.todo("should apply both surcharges to a cursed sword with enchantment 5 — 203 G");
    it.todo("should apply no high-enchantment surcharge to a plain sword with enchantment 4 — 115 G");
    it.todo("should apply only the curse surcharge to a cursed sword with enchantment 4 — 170 G");
    it.todo("should apply the curse surcharge only to the cursed item's base premium on a multi-item policy (cursed sword + plain amulet, 210 G before fee) — 236 G");
  });

  describe("policy-wide modifiers", () => {
    it.todo("should give 20 % loyalty discount to a customer with exactly 2 years (sword) — 95 G");
    it.todo("should give no loyalty discount to a customer with 1 year (sword) — 115 G");
    it.todo("should give 15 % follow-up discount on the second quote of a newcomer (sword, sword) — [115, 100] G");
    it.todo("should still apply the first-insurance surcharge on a long-standing customer's second contract (3 years, cursed sword enchantment 7) — 160 G");
  });

  describe("errors", () => {
    it.todo("should reject a quote containing an unknown item type (broomstick) with an error");
  });
});

describe("MHPCO Claim Office — claim", () => {
  describe("standard reimbursement", () => {
    it.todo("should pay full damage minus 100 G deductible for a regular steel sword enchantment 3, damage 500 G — payout 400 G, remainingCap 1600 G");
    it.todo("should pay full damage minus deductible for a rune (no enchantment/material), damage 200 G — payout 100 G, remainingCap 400 G");
  });

  describe("special clauses", () => {
    it.todo("should reimburse 50 % for a steel sword with enchantment 9, damage 1000 G — payout 400 G");
    it.todo("should fully reimburse a dragon-material sword with enchantment 5, damage 800 G — payout 700 G");
    it.todo("should let the 50 % rule win for a dragon-material sword with enchantment 9, damage 1000 G — payout 400 G");
    it.todo("should apply the 50 % rule at exactly enchantment 8 for a dragon-material sword, damage 1000 G — payout 400 G");
    it.todo("should round a payout of 350.5 G down to 350 G (steel sword enchantment 9, damage 901 G)");
  });

  describe("deductible per damage event", () => {
    it.todo("should apply the deductible once per damaged item (sword 500 G + amulet 300 G) — payout 600 G");
  });

  describe("insurance sum and cap", () => {
    it.todo("should cap a sword + amulet policy at 3200 G (sum 1600 G): sword damage 500 G — remainingCap 2800 G");
    it.todo("should base the cap on the unmodified insurance value for a cursed sword (cap 2000 G): damage 1500 G — payout 1400 G, remainingCap 600 G");
    it.todo("should not let the block discount reduce the insurance sum (sword + 3 runes, sum 1750 G, cap 3500 G): sword damage 500 G — remainingCap 3100 G");
    it.todo("should insure two swords for 2000 G with cap 4000 G: one sword damage 500 G — remainingCap 3600 G");
    it.todo("should treat two sword damage entries as separate damages with their own deductibles (two swords insured, 500 G each) — payout 800 G, remainingCap 3200 G");
    it.todo("should reduce the second of two successive 1500 G claims on a sword to the remaining cap — payouts [1400, 600] G, remainingCap [600, 0] G");
  });

  describe("policy references", () => {
    it.todo("should resolve the policy by the zero-based index of the quote step (claim against second quote)");
  });

  describe("errors", () => {
    it.todo("should reject a claim with more sword damages than swords insured (two damages, one sword) with an error");
    it.todo("should reject a claim damaging an amulet when only a sword is insured with an error");
    it.todo("should reject a claim damaging an item of unknown type with an error");
    it.todo("should reject a claim with a negative damage amount (-200) with an error");
  });
});
EOF
