const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const BASE_PREMIUM: Record<string, number> = { sword: 100 };

type Item = { type: string };
type QuoteStep = { op: "quote"; items: Item[] };
type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
type QuoteResult = { premium: number };

export const runScenario = (scenario: Scenario): { results: QuoteResult[] } => {
  const results = scenario.steps.map((step) => {
    const base = step.items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
    return { premium: base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE };
  });
  return { results };
};
EOF
