const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

type Item = { type: string };
type QuoteStep = { op: "quote"; items: Item[] };
type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
type QuoteResult = { premium: number };

const calculateBasePremium = (items: Item[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  if (runeCount === BLOCK_SIZE) return BLOCK_PREMIUM;
  return items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
};

const calculatePremium = (items: Item[]): number => {
  const basePremium = calculateBasePremium(items);
  return Math.ceil(basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
};

const quote = (step: QuoteStep): QuoteResult => ({ premium: calculatePremium(step.items) });

export const runScenario = (scenario: Scenario): { results: QuoteResult[] } => ({
  results: scenario.steps.map(quote),
});

